list=result.match(/href="([^"]+)">(.*?)<[\s\S]*?font>(.*?)<[\s\S]*?font>(.*?)<[\s\S]*?font>(.*?)</g);
arr=[];
number =Number(baseUrl.match(/pages=(\d+)/)[1]); number = 200*(number-1);
for(i in list){
	a=list[i].match(/href="([^"]+)">(.*?)<[\s\S]*?font>(.*?)<[\s\S]*?font>(.*?)<[\s\S]*?font>(.*?)</);
	chapternum = (Number(number)+(Number(i)+1))
	arr.push({
		"name": chapternum +"  | "+a[2].replace(/.*(重复|废废弃)章.*|^\d+[\.、]/g,''),
		"url":a[1],
		"info":"刊登时间："+a[3]+"•字数："+a[4]+"•价格："+a[5]
		})

	}
arr

